#include "world_types.h"
namespace npcai {
const char* WorldName(WorldKind k){switch(k){case WorldKind::TimeJump:return "time_jump";case WorldKind::TimeReversed:return "time_reversed";case WorldKind::Night:return "night";case WorldKind::RainStarted:return "rain_started";case WorldKind::RainStopped:return "rain_stopped";case WorldKind::PedAppeared:return "ped_appeared";case WorldKind::VehicleAppeared:return "vehicle_appeared";case WorldKind::PedGone:return "ped_gone";case WorldKind::VehicleGone:return "vehicle_gone";case WorldKind::WeaponHolstered:return "weapon_holstered";case WorldKind::PlayerLeft:return "player_left";case WorldKind::PlayerDiscontinuity:return "player_discontinuity";case WorldKind::Gunshot:return "gunshot";case WorldKind::Explosion:return "explosion";case WorldKind::Combat:return "combat";case WorldKind::Death:return "death";case WorldKind::VehicleDamage:return "vehicle_damage";}return "unknown";}
bool ParseWorldKind(const std::string& s,WorldKind& out){for(auto k:{WorldKind::TimeJump,WorldKind::TimeReversed,WorldKind::Night,WorldKind::RainStarted,WorldKind::RainStopped,WorldKind::PedAppeared,WorldKind::VehicleAppeared,WorldKind::PedGone,WorldKind::VehicleGone,WorldKind::WeaponHolstered,WorldKind::PlayerLeft,WorldKind::PlayerDiscontinuity,WorldKind::Gunshot,WorldKind::Explosion,WorldKind::Combat,WorldKind::Death,WorldKind::VehicleDamage})if(s==WorldName(k)){out=k;return true;}return false;}
bool Monitorable(WorldKind k){return k==WorldKind::TimeReversed || k==WorldKind::Night || k==WorldKind::RainStarted || k==WorldKind::PedAppeared || k==WorldKind::VehicleAppeared || k==WorldKind::WeaponHolstered || k==WorldKind::PlayerLeft;}
}
